1	//! Rust port of `tests/test10.cpp`.
2	//!
3	//! Builds a set of concentric polygonal rings — ring `layer` has
4	//! `(layer + 3) * 2` vertices on a circle of radius `(layer + 1) * 0.3 + layer * 0.1`
5	//! — hands them to the earcut triangulator as a single polygon (ring 0 is the
6	//! outer boundary, the rest are holes) and prints the resulting triangle
7	//! indices.
8	//!
9	//! Usage: `test10 [n]`, where `n` defaults to 10.
10	//!
11	//! Build standalone with `rustc -O test10.rs`, or with `cargo build --release`.
12	
13	#[path = "src/mapbox/mod.rs"]
14	mod mapbox;
15	
16	use std::f64::consts::PI;
17	use std::io::{self, Write};
18	
19	use mapbox::earcut;
20	
21	/// `std::atoi` as implemented by glibc: `(int) strtol(nptr, NULL, 10)`.
22	///
23	/// Leading whitespace is skipped, an optional sign is honoured, decimal digits
24	/// are consumed until the first non-digit, and the `long` result is *truncated*
25	/// (not clamped) to `int`. That truncation is observable: `atoi("4294967297")`
26	/// is `1`, and `atoi("2147483648")` is `-2147483648`. Values that overflow
27	/// `long` itself saturate to `LONG_MAX` / `LONG_MIN` before the cast.
28	fn c_atoi(s: &str) -> i32 {
29	    let bytes = s.as_bytes();
30	    let mut i = 0usize;
31	
32	    // isspace()
33	    while i < bytes.len() {
34	        match bytes[i] {
35	            b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r' => i += 1,
36	            _ => break,
37	        }
38	    }
39	
40	    let mut negative = false;
41	    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
42	        negative = bytes[i] == b'-';
43	        i += 1;
44	    }
45	
46	    let mut acc: i64 = 0;
47	    let mut overflowed = false;
48	    while i < bytes.len() && bytes[i].is_ascii_digit() {
49	        let digit = (bytes[i] - b'0') as i64;
50	        if !overflowed {
51	            match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
52	                Some(v) => acc = v,
53	                None => overflowed = true,
54	            }
55	        }
56	        i += 1;
57	    }
58	
59	    let value: i64 = if overflowed {
60	        if negative {
61	            i64::MIN
62	        } else {
63	            i64::MAX
64	        }
65	    } else if negative {
66	        -acc
67	    } else {
68	        acc
69	    };
70	
71	    value as i32
72	}
73	
74	fn main() {
75	    let args: Vec<String> = std::env::args().collect();
76	
77	    let mut n: i32 = 10;
78	    if args.len() > 1 {
79	        n = c_atoi(&args[1]);
80	    }
81	
82	    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
83	
84	    let mut layer: i32 = 0;
85	    while layer < n {
86	        let mut ring: Vec<[f64; 2]> = Vec::new();
87	        let radius = layer.wrapping_add(1) as f64 * 0.3;
88	
89	        // `(layer + 3) * 2`, both as the loop bound and as the angle divisor.
90	        let count = layer.wrapping_add(3).wrapping_mul(2);
91	
92	        let mut i: i32 = 0;
93	        while i < count {
94	            let angle = 2.0 * PI * i as f64 / count as f64;
95	            let offset = layer as f64 * 0.1;
96	            ring.push([
97	                (radius + offset) * angle.cos(),
98	                (radius + offset) * angle.sin(),
99	            ]);
100	            i += 1;
101	        }
102	
103	        polygon.push(ring);
104	        layer = layer.wrapping_add(1);
105	    }
106	
107	    let indices = earcut::<u32, _, _>(&polygon);
108	
109	    let stdout = io::stdout();
110	    let mut out = io::BufWriter::new(stdout.lock());
111	    for idx in &indices {
112	        let _ = write!(out, "{} ", idx);
113	    }
114	    let _ = out.flush();
115	}
