1	//! Output index types.
2	//!
3	//! Stands in for the `template <typename N = uint32_t>` parameter of
4	//! `mapbox::detail::Earcut`. The C++ code stores `static_cast<N>(i)` inside
5	//! every node, so the conversion is lossy for narrow `N`; `truncate` reproduces
6	//! that exactly.
7	
8	use std::fmt::Display;
9	
10	/// An integer type usable as a triangle index (`N` in the C++ template).
11	pub trait IndexType: Copy + Eq + Display {
12	    /// `static_cast<N>(v)`
13	    fn from_usize(v: usize) -> Self;
14	    /// Widen back to `usize`.
15	    fn to_usize(self) -> usize;
16	
17	    /// Round trip through `N`, i.e. exactly what `static_cast<N>(i)` keeps.
18	    #[inline]
19	    fn truncate(v: usize) -> usize {
20	        Self::from_usize(v).to_usize()
21	    }
22	}
23	
24	macro_rules! impl_index_type {
25	    ($($t:ty),*) => {
26	        $(
27	            impl IndexType for $t {
28	                #[inline]
29	                fn from_usize(v: usize) -> Self {
30	                    v as $t
31	                }
32	                #[inline]
33	                fn to_usize(self) -> usize {
34	                    self as usize
35	                }
36	            }
37	        )*
38	    };
39	}
40	
41	impl_index_type!(u8, u16, u32, u64, usize);
