// star-shaped (hence simple) polygon around (cx,cy)
fn star(rng: &mut Rng, cx: f64, cy: f64, rmin: f64, rmax: f64, n: usize) -> Vec<[f64;2]> {
    let mut angs: Vec<f64> = (0..n).map(|_| rng.f() * std::f64::consts::TAU).collect();
    angs.sort_by(|a,b| a.partial_cmp(b).unwrap());
    angs.iter().map(|&a| {
        let r = rmin + rng.f()*(rmax-rmin);
        [cx + r*a.cos(), cy + r*a.sin()]
    }).collect()
}

fn main() {
